// static
bool StructTraits<::chromeos_camera::mojom::BitstreamBuffer::DataView, ::chromeos_camera::mojom::BitstreamBufferPtr>::Read(
    ::chromeos_camera::mojom::BitstreamBuffer::DataView input,
    ::chromeos_camera::mojom::BitstreamBufferPtr* output) {
  bool success = true;
  ::chromeos_camera::mojom::BitstreamBufferPtr result(::chromeos_camera::mojom::BitstreamBuffer::New());
  
      if (success)
        result->id = input.id();
      if (success)
        result->memory_handle = input.TakeMemoryHandle();
      if (success)
        result->size = input.size();
      if (success)
        result->offset = input.offset();
      if (success && !input.ReadTimestamp(&result->timestamp))
        success = false;
      if (success && !input.ReadKeyId(&result->key_id))
        success = false;
      if (success && !input.ReadIv(&result->iv))
        success = false;
      if (success && !input.ReadSubsamples(&result->subsamples))
        success = false;
  *output = std::move(result);
  return success;
}

